-- EduSync Point 3B — industrial capability/RBAC engine
-- IMPORTANT: this migration creates the engine and capability catalog only.
-- Role assignments remain OWNER-DECIDED. Draft templates are not assignable.

CREATE TABLE IF NOT EXISTS capability_catalog (
  code varchar(128) PRIMARY KEY,
  domain_name varchar(96) NOT NULL,
  group_name varchar(128) NOT NULL,
  label varchar(220) NOT NULL,
  action_code varchar(48) NOT NULL,
  risk varchar(16) NOT NULL CHECK (risk IN ('LOW','MEDIUM','HIGH','CRITICAL')),
  offline_policy varchar(48) NOT NULL,
  audit_required boolean NOT NULL DEFAULT false,
  scope_types jsonb NOT NULL DEFAULT '[]'::jsonb,
  source_status varchar(48) NOT NULL,
  prerequisites jsonb NOT NULL DEFAULT '[]'::jsonb,
  outputs jsonb NOT NULL DEFAULT '[]'::jsonb,
  sensitive boolean NOT NULL DEFAULT false,
  notes text NOT NULL DEFAULT '',
  registry_version varchar(32) NOT NULL,
  active boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS rbac_roles (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  school_id uuid REFERENCES schools(id) ON DELETE CASCADE,
  code varchar(96) NOT NULL,
  label varchar(180) NOT NULL,
  description text NOT NULL DEFAULT '',
  level varchar(16) NOT NULL CHECK (level IN ('PLATFORM','SCHOOL')),
  kind varchar(32) NOT NULL CHECK (kind IN ('PLATFORM_STANDARD','SCHOOL_STANDARD','SCHOOL_CUSTOM')),
  status varchar(24) NOT NULL DEFAULT 'DRAFT' CHECK (status IN ('DRAFT','OWNER_APPROVED','ACTIVE','ARCHIVED')),
  version bigint NOT NULL DEFAULT 1,
  created_by_user_id uuid REFERENCES users(id),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CHECK (
    (level='PLATFORM' AND kind='PLATFORM_STANDARD' AND school_id IS NULL)
    OR (level='SCHOOL' AND kind='SCHOOL_STANDARD' AND school_id IS NULL)
    OR (level='SCHOOL' AND kind='SCHOOL_CUSTOM' AND school_id IS NOT NULL)
  )
);
CREATE UNIQUE INDEX IF NOT EXISTS uq_rbac_platform_standard_code ON rbac_roles(code) WHERE kind='PLATFORM_STANDARD';
CREATE UNIQUE INDEX IF NOT EXISTS uq_rbac_school_standard_code ON rbac_roles(code) WHERE kind='SCHOOL_STANDARD';
CREATE UNIQUE INDEX IF NOT EXISTS uq_rbac_school_custom_code ON rbac_roles(school_id,code) WHERE kind='SCHOOL_CUSTOM';

CREATE TABLE IF NOT EXISTS rbac_role_capabilities (
  role_id uuid NOT NULL REFERENCES rbac_roles(id) ON DELETE CASCADE,
  capability_code varchar(128) NOT NULL REFERENCES capability_catalog(code),
  granted_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (role_id, capability_code)
);

CREATE TABLE IF NOT EXISTS rbac_assignments (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id uuid NOT NULL REFERENCES users(id),
  role_id uuid NOT NULL REFERENCES rbac_roles(id),
  school_id uuid REFERENCES schools(id) ON DELETE CASCADE,
  membership_id uuid REFERENCES school_memberships(id) ON DELETE CASCADE,
  active boolean NOT NULL DEFAULT true,
  valid_from timestamptz NOT NULL DEFAULT now(),
  valid_until timestamptz,
  granted_by_user_id uuid REFERENCES users(id),
  reason text,
  version bigint NOT NULL DEFAULT 1,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CHECK (valid_until IS NULL OR valid_until > valid_from)
);
CREATE INDEX IF NOT EXISTS idx_rbac_assignments_user ON rbac_assignments(user_id) WHERE active;
CREATE INDEX IF NOT EXISTS idx_rbac_assignments_school ON rbac_assignments(school_id,membership_id) WHERE active;

CREATE TABLE IF NOT EXISTS rbac_assignment_scopes (
  assignment_id uuid NOT NULL REFERENCES rbac_assignments(id) ON DELETE CASCADE,
  scope_type varchar(16) NOT NULL CHECK (scope_type IN ('PLATFORM','SCHOOL','CYCLE','SECTION','CLASS')),
  scope_value varchar(128),
  CONSTRAINT uq_rbac_assignment_scopes UNIQUE NULLS NOT DISTINCT (assignment_id,scope_type,scope_value),
  CHECK (
    (scope_type IN ('PLATFORM','SCHOOL') AND scope_value IS NULL)
    OR (scope_type IN ('CYCLE','SECTION','CLASS') AND scope_value IS NOT NULL AND length(trim(scope_value))>0)
  )
);
-- Root scopes intentionally have no value; preserve uniqueness for them too.
CREATE UNIQUE INDEX IF NOT EXISTS uq_rbac_assignment_root_scope
  ON rbac_assignment_scopes(assignment_id,scope_type)
  WHERE scope_type IN ('PLATFORM','SCHOOL');

CREATE TABLE IF NOT EXISTS rbac_exception_grants (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id uuid NOT NULL REFERENCES users(id),
  school_id uuid NOT NULL REFERENCES schools(id) ON DELETE CASCADE,
  membership_id uuid NOT NULL REFERENCES school_memberships(id) ON DELETE CASCADE,
  capability_code varchar(128) NOT NULL REFERENCES capability_catalog(code),
  scope_type varchar(16) NOT NULL CHECK (scope_type IN ('SCHOOL','CYCLE','SECTION','CLASS')),
  scope_value varchar(128),
  valid_from timestamptz NOT NULL DEFAULT now(),
  valid_until timestamptz NOT NULL,
  granted_by_user_id uuid NOT NULL REFERENCES users(id),
  reason text NOT NULL,
  active boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT now(),
  CHECK (valid_until > valid_from),
  CHECK (length(trim(reason)) >= 5),
  CHECK (
    (scope_type='SCHOOL' AND scope_value IS NULL)
    OR (scope_type IN ('CYCLE','SECTION','CLASS') AND scope_value IS NOT NULL AND length(trim(scope_value))>0)
  )
);
CREATE INDEX IF NOT EXISTS idx_rbac_exception_effective
  ON rbac_exception_grants(school_id,user_id,capability_code,valid_until) WHERE active;

-- A draft/archived role cannot be assigned. School role/membership consistency is
-- checked here so no caller can bypass it by writing SQL directly.
CREATE OR REPLACE FUNCTION validate_rbac_assignment() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE
  r record;
  m record;
BEGIN
  SELECT id,school_id,level,kind,status INTO r FROM rbac_roles WHERE id=NEW.role_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'RBAC role not found'; END IF;
  IF r.status <> 'ACTIVE' THEN RAISE EXCEPTION 'RBAC role must be ACTIVE before assignment'; END IF;

  IF r.level='PLATFORM' THEN
    IF NEW.school_id IS NOT NULL OR NEW.membership_id IS NOT NULL THEN
      RAISE EXCEPTION 'Platform assignment cannot target a school';
    END IF;
  ELSE
    IF NEW.school_id IS NULL OR NEW.membership_id IS NULL THEN
      RAISE EXCEPTION 'School assignment requires school_id and membership_id';
    END IF;
    SELECT id,school_id,user_id INTO m FROM school_memberships WHERE id=NEW.membership_id;
    IF NOT FOUND OR m.school_id<>NEW.school_id OR m.user_id<>NEW.user_id THEN
      RAISE EXCEPTION 'Membership/user/school mismatch';
    END IF;
    IF r.kind='SCHOOL_CUSTOM' AND r.school_id<>NEW.school_id THEN
      RAISE EXCEPTION 'Custom role belongs to another school';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;
DROP TRIGGER IF EXISTS trg_validate_rbac_assignment ON rbac_assignments;
CREATE TRIGGER trg_validate_rbac_assignment BEFORE INSERT OR UPDATE ON rbac_assignments
FOR EACH ROW EXECUTE FUNCTION validate_rbac_assignment();

-- Capability catalog: immutable for normal app traffic; deployments/migrations own it.


-- First owner decision candidate only. This is deliberately DRAFT and therefore
-- cannot be assigned until Daniel validates it and a later owner-approved migration activates it.
VALUES ('MANAGER_SYSTEME','Manager système','Atelier Pro / propriétaire technique de la plateforme','PLATFORM','PLATFORM_STANDARD','DRAFT')
ON CONFLICT DO NOTHING;

SELECT r.id,c.code FROM rbac_roles r JOIN capability_catalog c ON c.domain_name='Atelier Pro'
WHERE r.code='MANAGER_SYSTEME' AND r.kind='PLATFORM_STANDARD'
ON CONFLICT DO NOTHING;

-- RLS and role-bound policies.
ALTER TABLE rbac_roles ENABLE ROW LEVEL SECURITY;
ALTER TABLE rbac_roles FORCE ROW LEVEL SECURITY;
ALTER TABLE rbac_role_capabilities ENABLE ROW LEVEL SECURITY;
ALTER TABLE rbac_role_capabilities FORCE ROW LEVEL SECURITY;
ALTER TABLE rbac_assignments ENABLE ROW LEVEL SECURITY;
ALTER TABLE rbac_assignments FORCE ROW LEVEL SECURITY;
ALTER TABLE rbac_assignment_scopes ENABLE ROW LEVEL SECURITY;
ALTER TABLE rbac_assignment_scopes FORCE ROW LEVEL SECURITY;
ALTER TABLE rbac_exception_grants ENABLE ROW LEVEL SECURITY;
ALTER TABLE rbac_exception_grants FORCE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS rbac_roles_platform ON rbac_roles;
CREATE POLICY rbac_roles_platform ON rbac_roles FOR ALL TO edusync_platform USING (true) WITH CHECK (true);
DROP POLICY IF EXISTS rbac_roles_tenant_read ON rbac_roles;
CREATE POLICY rbac_roles_tenant_read ON rbac_roles FOR SELECT TO edusync_tenant
USING ((kind='SCHOOL_STANDARD' AND school_id IS NULL) OR (kind='SCHOOL_CUSTOM' AND school_id=nullif(current_setting('app.current_school_id',true),'')::uuid));
DROP POLICY IF EXISTS rbac_roles_tenant_custom_write ON rbac_roles;
CREATE POLICY rbac_roles_tenant_custom_write ON rbac_roles FOR ALL TO edusync_tenant
USING (kind='SCHOOL_CUSTOM' AND school_id=nullif(current_setting('app.current_school_id',true),'')::uuid)
WITH CHECK (kind='SCHOOL_CUSTOM' AND school_id=nullif(current_setting('app.current_school_id',true),'')::uuid);

DROP POLICY IF EXISTS rbac_role_capabilities_platform ON rbac_role_capabilities;
CREATE POLICY rbac_role_capabilities_platform ON rbac_role_capabilities FOR ALL TO edusync_platform USING (true) WITH CHECK (true);
DROP POLICY IF EXISTS rbac_role_capabilities_tenant_read ON rbac_role_capabilities;
CREATE POLICY rbac_role_capabilities_tenant_read ON rbac_role_capabilities FOR SELECT TO edusync_tenant
USING (EXISTS (SELECT 1 FROM rbac_roles r WHERE r.id=role_id AND ((r.kind='SCHOOL_STANDARD' AND r.school_id IS NULL) OR (r.kind='SCHOOL_CUSTOM' AND r.school_id=nullif(current_setting('app.current_school_id',true),'')::uuid))));
DROP POLICY IF EXISTS rbac_role_capabilities_tenant_write ON rbac_role_capabilities;
CREATE POLICY rbac_role_capabilities_tenant_write ON rbac_role_capabilities FOR ALL TO edusync_tenant
USING (EXISTS (SELECT 1 FROM rbac_roles r WHERE r.id=role_id AND r.kind='SCHOOL_CUSTOM' AND r.school_id=nullif(current_setting('app.current_school_id',true),'')::uuid))
WITH CHECK (EXISTS (SELECT 1 FROM rbac_roles r WHERE r.id=role_id AND r.kind='SCHOOL_CUSTOM' AND r.school_id=nullif(current_setting('app.current_school_id',true),'')::uuid));

DROP POLICY IF EXISTS rbac_assignments_platform ON rbac_assignments;
CREATE POLICY rbac_assignments_platform ON rbac_assignments FOR ALL TO edusync_platform USING (true) WITH CHECK (true);
DROP POLICY IF EXISTS rbac_assignments_tenant ON rbac_assignments;
CREATE POLICY rbac_assignments_tenant ON rbac_assignments FOR ALL TO edusync_tenant
USING (school_id=nullif(current_setting('app.current_school_id',true),'')::uuid)
WITH CHECK (school_id=nullif(current_setting('app.current_school_id',true),'')::uuid);

DROP POLICY IF EXISTS rbac_assignment_scopes_platform ON rbac_assignment_scopes;
CREATE POLICY rbac_assignment_scopes_platform ON rbac_assignment_scopes FOR ALL TO edusync_platform USING (true) WITH CHECK (true);
DROP POLICY IF EXISTS rbac_assignment_scopes_tenant ON rbac_assignment_scopes;
CREATE POLICY rbac_assignment_scopes_tenant ON rbac_assignment_scopes FOR ALL TO edusync_tenant
USING (EXISTS (SELECT 1 FROM rbac_assignments a WHERE a.id=assignment_id AND a.school_id=nullif(current_setting('app.current_school_id',true),'')::uuid))
WITH CHECK (EXISTS (SELECT 1 FROM rbac_assignments a WHERE a.id=assignment_id AND a.school_id=nullif(current_setting('app.current_school_id',true),'')::uuid));

DROP POLICY IF EXISTS rbac_exception_grants_platform ON rbac_exception_grants;
CREATE POLICY rbac_exception_grants_platform ON rbac_exception_grants FOR ALL TO edusync_platform USING (true) WITH CHECK (true);
DROP POLICY IF EXISTS rbac_exception_grants_tenant ON rbac_exception_grants;
CREATE POLICY rbac_exception_grants_tenant ON rbac_exception_grants FOR ALL TO edusync_tenant
USING (school_id=nullif(current_setting('app.current_school_id',true),'')::uuid)
WITH CHECK (school_id=nullif(current_setting('app.current_school_id',true),'')::uuid);

-- Tenant can read the capability catalog to build the permission tree dynamically.
-- No tenant write policy exists.
ALTER TABLE capability_catalog ENABLE ROW LEVEL SECURITY;
ALTER TABLE capability_catalog FORCE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS capability_catalog_platform ON capability_catalog;
CREATE POLICY capability_catalog_platform ON capability_catalog FOR ALL TO edusync_platform USING (true) WITH CHECK (true);
DROP POLICY IF EXISTS capability_catalog_tenant_read ON capability_catalog;
CREATE POLICY capability_catalog_tenant_read ON capability_catalog FOR SELECT TO edusync_tenant USING (active=true);
